export function TermIcon({ slug, size = 48, label, className = "" }: TermIconProps) {
  const kind = termIcons[slug as keyof typeof termIcons];
  if (!kind) throw new Error(`Missing term icon mapping: ${slug}`);
  const labelled = Boolean(label);
  return (
    <span className={`term-icon ${className}`.trim()} style={{ "--term-icon-size": `${size}px` } as CSSProperties} role={labelled ? "img" : undefined} aria-label={label} aria-hidden={labelled ? undefined : true}>
      <svg viewBox="8 8 48 48" focusable="false" aria-hidden={labelled ? undefined : true}>
        <g className="term-icon-glyph"><Glyph kind={kind} /></g>
      </svg>
    </span>
  );
}

